PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT,display_name TEXT UNIQUE,avatar TEXT,bio TEXT,balance INTEGER NOT NULL DEFAULT 10000,bank INTEGER NOT NULL DEFAULT 0,level INTEGER NOT NULL DEFAULT 1,xp INTEGER NOT NULL DEFAULT 0,energy INTEGER NOT NULL DEFAULT 100,max_energy INTEGER NOT NULL DEFAULT 100,last_energy_regen INTEGER NOT NULL DEFAULT (strftime('%s','now')),pet_equipped TEXT,win_streak INTEGER NOT NULL DEFAULT 0,max_win_streak INTEGER NOT NULL DEFAULT 0,login_streak INTEGER NOT NULL DEFAULT 1,max_login_streak INTEGER NOT NULL DEFAULT 1,total_wins INTEGER NOT NULL DEFAULT 0,total_losses INTEGER NOT NULL DEFAULT 0,total_bets INTEGER NOT NULL DEFAULT 0,total_wagered INTEGER NOT NULL DEFAULT 0,total_won INTEGER NOT NULL DEFAULT 0,biggest_win INTEGER NOT NULL DEFAULT 0,vip_tier INTEGER NOT NULL DEFAULT 0,clan_id INTEGER,banned INTEGER NOT NULL DEFAULT 0,ban_reason TEXT,muted INTEGER NOT NULL DEFAULT 0,muted_until INTEGER NOT NULL DEFAULT 0,win_rate_override REAL,last_daily INTEGER NOT NULL DEFAULT 0,last_login INTEGER NOT NULL DEFAULT (strftime('%s','now')),last_spin INTEGER NOT NULL DEFAULT 0,settings TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),updated_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),deleted_at INTEGER);
CREATE INDEX IF NOT EXISTS idx_users_balance ON users(balance DESC); CREATE INDEX IF NOT EXISTS idx_users_level ON users(level DESC,xp DESC); CREATE INDEX IF NOT EXISTS idx_users_bank ON users(bank DESC); CREATE INDEX IF NOT EXISTS idx_users_login_streak ON users(login_streak DESC); CREATE INDEX IF NOT EXISTS idx_users_max_win_streak ON users(max_win_streak DESC); CREATE INDEX IF NOT EXISTS idx_users_total_wins ON users(total_wins DESC); CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
CREATE TABLE IF NOT EXISTS pets(id TEXT PRIMARY KEY,name TEXT NOT NULL,icon TEXT NOT NULL,description TEXT,rarity TEXT DEFAULT 'common',money_bonus REAL NOT NULL DEFAULT 0,xp_bonus REAL NOT NULL DEFAULT 0,price INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,order_index INTEGER DEFAULT 0,max_level INTEGER DEFAULT 10,upgrade_cost_per_level INTEGER DEFAULT 0,created_at INTEGER NOT NULL DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS user_pets(user_id TEXT NOT NULL,pet_id TEXT NOT NULL,level INTEGER NOT NULL DEFAULT 1,equipped INTEGER NOT NULL DEFAULT 0,acquired_at INTEGER NOT NULL DEFAULT (strftime('%s','now')),PRIMARY KEY(user_id,pet_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(pet_id) REFERENCES pets(id));
CREATE TABLE IF NOT EXISTS bets(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,game TEXT NOT NULL,amount INTEGER NOT NULL,result TEXT NOT NULL,payout INTEGER DEFAULT 0,multiplier REAL DEFAULT 0,metadata TEXT,balance_after INTEGER,created_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))); CREATE INDEX IF NOT EXISTS idx_bets_user ON bets(user_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_bets_game ON bets(game,created_at DESC);
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,type TEXT NOT NULL,amount INTEGER NOT NULL,balance_before INTEGER,balance_after INTEGER,note TEXT,meta TEXT,created_at INTEGER NOT NULL DEFAULT (strftime('%s','now'))); CREATE INDEX IF NOT EXISTS idx_trans_user ON transactions(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS quest_templates(id TEXT PRIMARY KEY,type TEXT NOT NULL,title TEXT NOT NULL,target INTEGER NOT NULL,reward_money INTEGER DEFAULT 0,reward_xp INTEGER DEFAULT 0,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS user_quests(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,quest_id TEXT NOT NULL,progress INTEGER DEFAULT 0,completed INTEGER DEFAULT 0,claimed INTEGER DEFAULT 0,reset_at INTEGER,expires_at INTEGER,created_at INTEGER DEFAULT (strftime('%s','now')),UNIQUE(user_id,quest_id,reset_at));
CREATE TABLE IF NOT EXISTS achievement_templates(id TEXT PRIMARY KEY,title TEXT NOT NULL,target INTEGER DEFAULT 1,reward_money INTEGER DEFAULT 0,reward_xp INTEGER DEFAULT 0,hidden INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS user_achievements(user_id TEXT NOT NULL,achievement_id TEXT NOT NULL,progress INTEGER DEFAULT 0,unlocked_at INTEGER,claimed_at INTEGER,PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS coupons(code TEXT PRIMARY KEY,amount INTEGER NOT NULL DEFAULT 0,pet_id TEXT,item_code TEXT,max_uses INTEGER DEFAULT 1,used_count INTEGER DEFAULT 0,created_by TEXT,expires_at INTEGER,active INTEGER DEFAULT 1,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS coupon_uses(coupon_code TEXT,user_id TEXT,used_at INTEGER DEFAULT (strftime('%s','now')),PRIMARY KEY(coupon_code,user_id));
CREATE TABLE IF NOT EXISTS jackpot(id INTEGER PRIMARY KEY CHECK(id=1),amount INTEGER DEFAULT 1000000,last_winner TEXT,last_won_at INTEGER,updated_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS jackpot_history(id INTEGER PRIMARY KEY AUTOINCREMENT,winner_id TEXT,amount INTEGER,game TEXT,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,name TEXT,description TEXT,icon TEXT,start_at INTEGER,end_at INTEGER,active INTEGER DEFAULT 0,config TEXT,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS clans(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,tag TEXT,icon TEXT DEFAULT '🛡️',description TEXT,owner_id TEXT NOT NULL,level INTEGER DEFAULT 1,xp INTEGER DEFAULT 0,bank INTEGER DEFAULT 0,member_count INTEGER DEFAULT 1,max_members INTEGER DEFAULT 20,public INTEGER DEFAULT 1,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS clan_members(clan_id INTEGER NOT NULL,user_id TEXT NOT NULL,role TEXT DEFAULT 'member',contribution INTEGER DEFAULT 0,joined_at INTEGER DEFAULT (strftime('%s','now')),PRIMARY KEY(clan_id,user_id));
CREATE TABLE IF NOT EXISTS chat_channels(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,type TEXT DEFAULT 'public',clan_id INTEGER,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS chat_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,channel_id INTEGER NOT NULL,user_id TEXT NOT NULL,content TEXT NOT NULL,type TEXT DEFAULT 'text',reply_to INTEGER,meta TEXT,deleted INTEGER DEFAULT 0,created_at INTEGER DEFAULT (strftime('%s','now'))); CREATE INDEX IF NOT EXISTS idx_chat_channel ON chat_messages(channel_id,created_at DESC);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,type TEXT NOT NULL,title TEXT,body TEXT,icon TEXT,read INTEGER DEFAULT 0,action_url TEXT,created_at INTEGER DEFAULT (strftime('%s','now'))); CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id,read,created_at DESC);
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,actor_id TEXT,action TEXT NOT NULL,target TEXT,meta TEXT,ip TEXT,level TEXT DEFAULT 'info',created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS items(code TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT,icon TEXT,type TEXT NOT NULL,price INTEGER NOT NULL DEFAULT 0,stackable INTEGER DEFAULT 1,effect TEXT,active INTEGER DEFAULT 1,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS inventory(user_id TEXT NOT NULL,item_code TEXT NOT NULL,quantity INTEGER DEFAULT 1,acquired_at INTEGER DEFAULT (strftime('%s','now')),PRIMARY KEY(user_id,item_code));
CREATE TABLE IF NOT EXISTS trade_offers(id INTEGER PRIMARY KEY AUTOINCREMENT,from_user TEXT NOT NULL,to_user TEXT NOT NULL,offer_money INTEGER DEFAULT 0,offer_items TEXT,offer_pets TEXT,request_money INTEGER DEFAULT 0,request_items TEXT,request_pets TEXT,status TEXT DEFAULT 'pending',message TEXT,created_at INTEGER DEFAULT (strftime('%s','now')),expires_at INTEGER,resolved_at INTEGER);
CREATE TABLE IF NOT EXISTS seasons(id INTEGER PRIMARY KEY,name TEXT NOT NULL,start_at INTEGER,end_at INTEGER,active INTEGER DEFAULT 0,config TEXT);
CREATE TABLE IF NOT EXISTS season_pass(user_id TEXT NOT NULL,season_id INTEGER NOT NULL,tier INTEGER DEFAULT 0,xp INTEGER DEFAULT 0,premium INTEGER DEFAULT 0,claimed_tiers TEXT DEFAULT '[]',updated_at INTEGER DEFAULT (strftime('%s','now')),PRIMARY KEY(user_id,season_id));
CREATE TABLE IF NOT EXISTS season_rewards(season_id INTEGER NOT NULL,tier INTEGER NOT NULL,premium INTEGER DEFAULT 0,type TEXT,reward TEXT,PRIMARY KEY(season_id,tier,premium));
CREATE TABLE IF NOT EXISTS referrals(user_id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,referrer_id TEXT,total_invited INTEGER DEFAULT 0,total_earned INTEGER DEFAULT 0,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS referral_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,referrer_id TEXT,referee_id TEXT,reward INTEGER DEFAULT 0,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS daily_rewards(user_id TEXT NOT NULL,day_index INTEGER NOT NULL,claimed_at INTEGER DEFAULT (strftime('%s','now')),PRIMARY KEY(user_id,day_index));
CREATE TABLE IF NOT EXISTS admin_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id TEXT NOT NULL,command TEXT NOT NULL,args TEXT,result TEXT,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS system_stats(key TEXT PRIMARY KEY,value TEXT,updated_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS banned_words(word TEXT PRIMARY KEY,added_by TEXT,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS user_settings(user_id TEXT PRIMARY KEY,sound_on INTEGER DEFAULT 1,music_on INTEGER DEFAULT 1,haptic_on INTEGER DEFAULT 1,particles_on INTEGER DEFAULT 1,language TEXT DEFAULT 'vi',theme TEXT DEFAULT 'dark',perf_tier TEXT DEFAULT 'auto',notifications_on INTEGER DEFAULT 1,updated_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS maintenance(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER DEFAULT 0,message TEXT DEFAULT 'Hệ thống đang bảo trì.');
CREATE TABLE IF NOT EXISTS game_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,game TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER DEFAULT (strftime('%s','now')),updated_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS game_rounds(id INTEGER PRIMARY KEY AUTOINCREMENT,game TEXT NOT NULL,server_seed_hash TEXT NOT NULL,created_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS metrics(key TEXT PRIMARY KEY,value INTEGER DEFAULT 0,updated_at INTEGER DEFAULT (strftime('%s','now')));
CREATE TABLE IF NOT EXISTS user_devices(user_id TEXT NOT NULL,device_key TEXT NOT NULL,last_seen INTEGER,PRIMARY KEY(user_id,device_key));
